text.resilience364At:
function resilience364At(x,y,b){
  if(!inMap(x,y))return {pump:false,center:false,shelter:false,floodMul:1,floodClear:.15,damageMul:1,casualtyMul:1,recovery:0};
  const i=idx(x,y),pump=COV.pump[i]>0,center=COV.resilience[i]>0,shelter=COV.shelter[i]>0;
  const resident=!!(b&&b.k===1); // T364c：避難傷亡倍率只覆蓋既有隨機住宅池；固定社宅不加入該池，以免改動共用亂數流
  const legacyFlood=drainageLegacy454(); // T454：正常模式角色分工；pump/shelter 不再用半徑直接阻止水出現
  const floodMul=legacyFlood?(pump?PUMP_FLOOD_DAMAGE_MUL:1)*(center?DISASTER_CENTER_DAMAGE_MUL:1)*(shelter?SHELTER_CASUALTY_MUL:1):1;
  const casualtyMul=shelter&&resident?SHELTER_CASUALTY_MUL:1;
  const floodClear=legacyFlood?(pump?PUMP_FLOOD_CLEAR_CHANCE:center?DISASTER_CENTER_FLOOD_CLEAR_CHANCE:shelter?SHELTER_FLOOD_CLEAR_CHANCE:.15):.15;
  return {pump,center,shelter,floodMul,floodClear,damageMul:center?DISASTER_CENTER_DAMAGE_MUL:1,casualtyMul,recovery:center?DISASTER_CENTER_RECOVERY_CHANCE:0};
}

text.preDeath:
// 死亡與墓園前置處理（T38）：既有死亡事件的懲罰標記與自動消退
const deathPenalty=new Uint8Array(N*N);
let cemCount=0,bigCem=0;
for(const i of tickBld){const b=tiles[i].bld;if(b&&b.k===16)cemCount++;if(b&&b.k===54&&!b.ref)bigCem++;} // T233：大墓園 root 計數
let cremPre342=0;for(const i2 of tickBld){const b2=tiles[i2].bld;if(b2&&b2.k===107)cremPre342++;}
const cemCap=cemCount*3+bigCem*24+cremPre342*40; /* T342：火葬場高吞吐（40） */ // T233：大墓園容量 24（8 座墓園）
let soothed=0;
for(const i of tickBld){
  const b=tiles[i].bld;
  if(!b||b.k!==1||!b.death)continue;
  b.deathAge=(b.deathAge||0)+1;
  if(b.deathAge>=10){b.death=0;b.deathAge=0;b.sick=0;continue;}
  const x=i%N,y=(i/N)|0;
  const covered=COV.cemetery[i]>0||COV.cem2[i]>0||(COV.crem&&COV.crem[i]>0);     // T61：墓園半徑10覆蓋（原 countNear k===16）；T233：大墓園 cem2 半徑16 同效
  if(covered&&soothed<cemCap){soothed++;continue;}
  // 未安撫：半徑 6 內其他住宅幸福 -0.1
  for(let dy=-6;dy<=6;dy++)for(let dx=-6;dx<=6;dx++){
    const nx=x+dx,ny=y+dy;
    if(!inMap(nx,ny))continue;
    const j=idx(nx,ny),nb=tiles[j].bld;
    if(nb&&nb.k===1&&!nb.death)deathPenalty[j]=1;
  }
}

text.fire:
// 火災（升級段之後）：起火→蔓延→推進燃燒/燒毀成焦土
const burning=[];
for(const i of tickBld){const b=tiles[i].bld;if(b&&b.k<=3&&b.fire)burning.push(i);}
let fireAlert=false;
for(const i of tickBld){                                // 起火擲骰（未燃 k≤3）
  const b=tiles[i].bld;
  if(!b||b.k>3||b.fire)continue;
  let p=.0005*(b.k===3?3:1)*b.lv;
  if(drought)p*=DROUGHT_FIRE_MULT;
  if(pol&&pol.smokeDetect)p*=.6; // T327：煙霧偵測（只改機率不改 R() 消耗次數＝鐵律2）                     // T137：乾旱期間起火機率×2.5（非乾旱精確恆等 ×1）
  const x=i%N,y=(i/N)|0;                               // 消防局半徑 9 覆蓋 → 起火率 -85%
  if((COV.fire[i]>0||(COV.fire2&&COV.fire2[i]>0)||(COV.fireHQ&&COV.fireHQ[i]>0)))p*=.15;
  else if(COV.firewatch&&COV.firewatch[i]>0)p*=.45; // T340：瞭望塔＝弱火險（有正規消防時不疊加）                             // T61：消防局半徑9覆蓋（原 countNear k===6）
  {const r364=resilience364At(x,y,b);p*=r364.damageMul*r364.casualtyMul;}
  p*=tq('A4a',1.10,1)*tq('A4b',.85,1)*tq('B3',.90,1)*sq('ind',1.08,1)*sq('green',.90,1);
  if(R()<p){
    b.fire=1;
    if(!fireAlert){toast('🔥 '+townName+'發生火災！點擊燃燒的建築滅火','bad',x,y);sErr();fireAlert=true;}
  }
}
for(const i of burning){                               // 蔓延：20% 點燃 Chebyshev 1 內未燃建築
  if(R()<.20){
    const x=i%N,y=(i/N)|0,opts=[];
    for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){
      if(!dx&&!dy)continue;
      const nx=x+dx,ny=y+dy;
      if(!inMap(nx,ny))continue;
      const ni=idx(nx,ny),nb=tiles[ni].bld;
      if(nb&&nb.k<=3&&!nb.fire)opts.push([ni,nb]);
    }
    if(opts.length){const[ni,nb]=opts[ri(opts.length)];if(!disasterBlocked364(ni%N,(ni/N)|0,nb,36484))nb.fire=1;}
  }
}
for(const i of burning){                               // 推進燃燒天數；fire>=5 燒毀成焦土（T119：覆蓋內撲滅改由消防車抵達執行，見 updFireTrucks，不再次日瞬滅）
  const t=tiles[i],b=t.bld;
  if(!b||!b.fire)continue;
  const x=i%N,y=(i/N)|0;
  const r364=resilience364At(x,y,b);
  if(r364.recovery&&streetHash(x,y,day+36485)<r364.recovery)b.fire=Math.max(0,b.fire-1);else b.fire++;
  if(b.fire>=5){if(b.k===3)stampPolSrc(x,y,3,-1);t.bld=null;t.ruin=1;insPayout(x,y);} // zone 保留；T110：工業燒毀→撤銷污染源
}

text.crime:
// 犯罪（T32）：未受警察局半徑10覆蓋的 k≤3 建築每天小機率發生犯罪
let crimeAlert=false;
for(const i of tickBld){
  const b=tiles[i].bld;
  if(!b||b.k>3||b.crime)continue;
  const x=i%N,y=(i/N)|0;
  if(COV.police[i]>0||COV.police2[i]>0)continue; // T61：警察局半徑10覆蓋則受保護（原 countNear k===11）；T222：派出所小半徑同效
  if(!(COV.prison&&COV.prison[i]>0)&&R()<.001*(b.k===2?2:1)*b.lv*(pol&&pol.curfew?.6:1)*(pol&&pol.nightMarket?1.15:1)*(pol&&pol.parkNight?1.05:1)*((COV.court&&COV.court[i]>0)?.5:1)*tq('B2',.92,1)*tq('B4b',1.05,1)*tq('B7',.90,1)*nightCrimeMul487(i,b)){ // T487：夜間照明＋警力共同降低風險；照明不替代警察 // T67：監獄半徑8覆蓋則防犯罪（原 countNear k===31，O(N)→O(1)）；T122 宵禁：犯罪率×0.6；T139：法院半徑10覆蓋配合警局再降犯罪率×0.5（未放置時恆×1）
    b.crime=1;markLandDirty(x,y,4); // T315：犯罪影響地價，標記影響框
    if(!crimeAlert){toast('🚓 '+townName+'發生犯罪！點擊受害建築處理','bad',x,y);sErr();crimeAlert=true;}
  }
}
// 廢棄（T71）：犯罪持續未被玩家處理（crimeBtn/GV.clearCrime）滿 15 天後每天 5% 機率轉為廢棄；
// 廢棄建築的停稅由既有經濟段 `!b.abandoned` 判定（原已預留，本卡補上唯一賦值來源）
let abandonAlert=false;
for(const i of tickBld){
  const b=tiles[i].bld;
  if(!b||b.k>3||!b.crime||b.abandoned)continue;
  b.crimeDays=(b.crimeDays||0)+1;
  if(b.crimeDays>=15&&R()<.05){
    b.abandoned=1;
    if(!abandonAlert){toast('🏚️ '+townName+'有建築因長期犯罪而廢棄，已停止繳稅','bad',i%N,(i/N)|0);sErr();abandonAlert=true;}
  }
}

text.disease:
// 生病（T33/T34）：未受健康設施覆蓋的住宅每天小機率生病；醫院覆蓋內次日康復，診所覆蓋內每天50%機率康復
const medCap387=(!window.__noCivicServices495&&civic495.ready)?Math.max(0,Math.floor(civic495.health.effectiveBeds)):((flowStat384&&flowStat384.ok&&flowStat384.med)?flowStat384.med.cap:Infinity); // T495：治療與面板共讀同一有效床位；rollback/首日保留舊口徑
let medCured387=0,medQueued387=0; // T387b：今日治癒/滯留（tick 區域，零守衛面）
let sickAlert=false;
for(const i of tickBld){
  const b=tiles[i].bld;
  if(!b||b.k!==1)continue;
  const x=i%N,y=(i/N)|0;
  const ca495=civicHealthAccess495(i),hospital=ca495?ca495.hospital:(COV.hospital[i]>0||(COV.ambulance&&COV.ambulance[i]>0)||(COV.megahosp&&COV.megahosp[i]>0)||(COV.medcamp&&COV.medcamp[i]>0)); // T495：Coverage 只由有設備、有職員且可運作的醫療設施蓋印
  const clinic=ca495?ca495.clinic:COV.clinic[i]>0;
  const covered=hospital||clinic;
  if(b.sick){
    if(hospital){if(medCured387<medCap387){b.sick=0;medCured387++;}else medQueued387++;} // T387b：床位門檻（原分支無 R，改後仍無 R）；醫院覆蓋+有床 → 次日必康復
    else if(clinic&&R()<.5){if(medCured387<medCap387){b.sick=0;medCured387++;}else medQueued387++;} // T387b：R() 照擲、結果被床位遮蔽（消耗序恆等=T364d attempted 精神）；診所覆蓋 → 50% 且有床才康復
    continue;
  }
  if(!covered&&R()<.001*b.lv+(waterLegacy449()?0:waterDiseaseRisk472(i))){ // T472：沿用原本唯一一次 R()，只微調門檻；不增加 RNG 次數／順序
    b.sick=1;
    if(!sickAlert){toast('🏥 '+townName+'爆發疾病！點擊生病住宅處理','bad',x,y);sErr();sickAlert=true;}
  }
}
// 生病→死亡轉化（T38）：sick≥3 天未康復每天 10% 轉死亡
let deathAlert=false,sickN387=0; // T387a：同時病患計數（純觀測搭既有迴圈＝T145 svcSamples 先例；tick 區域變數=零守衛面）
for(const i of tickBld){
  const b=tiles[i].bld;
  if(!b||b.k!==1||!b.sick||b.death)continue;
  sickN387++;b.sickDays=(b.sickDays||0)+1; // T387a：計「今日仍病者」（病癒後、轉死擲骰前）
  if(b.sickDays>=3&&R()<.10){
    b.death=1;b.deathAge=0;b.sick=0;b.sickDays=0;
    if(!deathAlert){toast('💀 發生憾事！請增設健康設施或墓園','bad',i%N,(i/N)|0);sErr();deathAlert=true;}
  }
}

text.buttons:
const cb=$('#crimeBtn');                               // 處理犯罪按鈕（T32）
if(cb)cb.addEventListener('click',()=>{
  const bb=inMap(x,y)?T(idx(x,y)).bld:null;
  if(!bb||!bb.crime)return;
  bb.crime=0;bb.crimeDays=0;markLandDirty(x,y,4); // T315；T412：歸零廢棄倒數＝與警車到場（updPoliceCars onArrive）同語義——原本只清旗＝玩家親手處理反而比等警車「虧」
  toast('🚓 犯罪已處理','gold');updHud();hideInfo();
});
const sb=$('#sickBtn');                                // 治療生病按鈕（T33）
if(sb)sb.addEventListener('click',()=>{
  const bb=inMap(x,y)?T(idx(x,y)).bld:null;
  if(!bb||!bb.sick)return;
  if(money>=50){money-=50;bb.sick=0;toast('🏥 病情已控制','gold');updHud();hideInfo();}
  else{toast('資金不足！治療需 $50','bad');sErr();}
});
const fb=$('#fireBtn');                                // 滅火按鈕（事件綁定，不用內聯 onclick）
if(fb)fb.addEventListener('click',()=>{
  const bb=inMap(x,y)?T(idx(x,y)).bld:null;
  if(!bb||!bb.fire)return;
  if(money>=30){money-=30;bb.fire=0;toast('🧯 火勢已撲滅！','gold');updHud();hideInfo();}
  else{toast('資金不足！滅火需 $30','bad');sErr();}
});
